#include <iostream>
#include <cmath>

int main() {
    std::cout << 2 + 3 * 4 << std::endl;            // 14
    std::cout << (2 + 3) * 4 << std::endl;          // 20
    std::cout << 10 - std::pow(2, 3) << std::endl;  // 2
    std::cout << 7 * (60 + 30) << std::endl;        // 630
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    double summe = 0.1 + 0.2;
    std::cout << summe << std::endl;                           // 0.3
    std::cout << std::setprecision(17) << summe << std::endl;  // 0.30000000000000004
    std::cout << std::fixed << std::setprecision(2) << summe << std::endl;  // 0.30
    return 0;
}

